  json: {
    base64Image: base64String,
    mimeType: item.binary?.data?.mimeType || 'image/jpeg',
    chatId: item.json.message?.chat?.id?.toString() || '',
    messageId: item.json.message?.message_id || 0,
    fileId: fileId
  }
};

