const input = $input.first().json;
let geminiText = input.candidates?.[0]?.content?.parts?.[0]?.text || "{}";
geminiText = geminiText.replace(/```json/g, '').replace(/```/g, '').trim();
let parsed = {};
try {
 parsed = JSON.parse(geminiText);
} catch (e) {
 parsed = {};
}
return {
 json: {
 product_name: parsed.product_name || null,
 brand: parsed.brand || null,
 product_category: parsed.product_category || null,
 product_type: parsed.product_type || null,
 model: parsed.model || null,
 part_number: parsed.part_number || null,
 visible_text: parsed.visible_text || [],
 base64Image: input.base64Image,
 mimeType: input.mimeType,
 chatId: input.chatId,
 messageId: input.messageId,
 fileId: input.fileId
 }
};

// Ambil hasil Product Identification
const visionItems = $items("Parse Product Identification");

if (!visionItems || visionItems.length === 0) {
  return [
    {
      json: {
        error: "Parse Product Identification tidak menghasilkan data"
      }
    }
  ];
}

const visionData = visionItems[0].json;

// Ambil hasil langsung dari SQL node
const sqlItems = $items("Vector Search");

const candidates = sqlItems.map(item => item.json);

// Jika SQL tidak menghasilkan produk
if (candidates.length === 0) {
  return [
    {
      json: {
        ...visionData,
        matchedProduct: null,
        matchScore: 0,
        candidateCount: 0,
        status: "NO_CANDIDATE_FOUND"
      }
    }
  ];
}

let bestMatch = null;
let highestScore = -1;

for (const candidate of candidates) {
  let score = 0;

  // Part Number = bobot tertinggi
  if (
    visionData.part_number &&
    candidate.part_number &&
    String(candidate.part_number).trim().toLowerCase() ===
    String(visionData.part_number).trim().toLowerCase()
  ) {
    score += 10;
  }

  // Brand
  if (
    visionData.brand &&
    candidate.brand &&
    String(candidate.brand).trim().toLowerCase() ===
    String(visionData.brand).trim().toLowerCase()
  ) {
    score += 5;
  }

  // Product Name
  if (
    visionData.product_name &&
    candidate.product_name
  ) {
    const visionProduct = String(visionData.product_name).trim().toLowerCase();
    const candidateProduct = String(candidate.product_name).trim().toLowerCase();

    if (
      candidateProduct.includes(visionProduct) ||
      visionProduct.includes(candidateProduct)
    ) {
      score += 3;
    }
  }

  // Product Category
  if (
    visionData.product_category &&
    candidate.product_category &&
    String(candidate.product_category).trim().toLowerCase() ===
    String(visionData.product_category).trim().toLowerCase()
  ) {
    score += 2;
  }

  // Product Type
  if (
    visionData.product_type &&
    candidate.product_type &&
    String(candidate.product_type).trim().toLowerCase() ===
    String(visionData.product_type).trim().toLowerCase()
  ) {
    score += 2;
  }

  if (score > highestScore) {
    highestScore = score;
    bestMatch = candidate;
  }
}

return [
  {
    json: {
      ...visionData,

      matchedProduct: bestMatch,

      matchScore: highestScore,

      candidateCount: candidates.length,

      status: bestMatch
        ? "MATCH_FOUND"
        : "NO_MATCH"
    }
  }
];

const input = $input.first().json;
