const ctx = $input.first().json;

// Menyiapkan teks judul dan detail dari RAG Context
const productName = (ctx.product_name || "SPARE PART MOTOR").toUpperCase();
const brand = (ctx.brand || "YSP").toUpperCase();
const model = ctx.model ? `UNTUK ${ctx.model.toUpperCase()}` : "";
const fullTitle = `${brand} ${productName} ${model}`.trim();

const prompt = [
  'Create a professional e-commerce product poster for an online motorcycle spare part store, based on the provided product image.',

  'LAYOUT & OVERLAY ELEMENTS TO ADD:',
  `1. TOP LEFT LOGO: Add a blue rectangular logo badge with white text '${brand} GENUINE PARTS'.`,
  `2. TOP RIGHT BADGE: Add a circular blue stamp badge with text '100% ORIGINAL'.`,
  `3. BOTTOM TEXT OVERLAY: At the bottom center, render bold, clean, black typography reading: '${fullTitle}'.`,
  '4. BACKGROUND: Clean off-white studio background with subtle grey abstract automotive/tire streak textures.',

  'PRODUCT PRESERVATION RULES:',
  'Keep the original physical spare part product centered, visible, and unchanged in shape, texture, and color.',
  'If there are multiple parts (like kampas rem or rumah roller), arrange them neatly side-by-side in the center.',

  'STYLE:',
  'Square 1:1 aspect ratio, clean Indonesian marketplace catalog style, sharp typography, professional product presentation.'
].join('\n');

return [
  {
    json: {
      ...ctx,
      wanPrompt: prompt
    }
  }
];

