const input = $input.first().json;

const choices = input.output?.choices || [];

if (!choices.length) {
  throw new Error(
    `Wan API tidak mengembalikan choices. Response: ${JSON.stringify(input)}`
  );
}

const content = choices[0]?.message?.content || [];

const imageContent = content.find(
  item => item.type === "image" && item.image
);

if (!imageContent?.image) {
  throw new Error(
    `Tidak menemukan generated image URL. Content: ${JSON.stringify(content)}`
  );
}

return {
  json: {
    ...input,
    generatedImageUrl: imageContent.image
  }
};

const product = $json;

const productText = [
  `Product Name: ${product.product_name || ''}`,
  `Brand: ${product.brand || ''}`,
  `Category: ${product.product_category || ''}`,
  `Product Type: ${product.product_type || ''}`,
  `Model: ${product.model || ''}`,
  `Part Number: ${product.part_number || ''}`,
  `Spec Length: ${product.spec_length || ''}`,
  `Description: ${product.description || ''}`,
  `Badge: ${product.badge || ''}`,
  `Store: ${product.store_name || ''}`,
  `Keywords: ${product.keywords || ''}`
].join(' ');

return {
  json: {
    ...product,
    productText
  }
};

const embedding = $json.embedding.values;
const product = $('Build Product Text').first().json;

return {
  json: {
    product_name: product.product_name,
    embedding: embedding
  }
};

const product = $input.first().json;

const productText = [
  product.product_name,
  product.brand,
  product.product_category,
  product.product_type,
  product.model,
  product.part_number,
  product.description,
  product.keywords
]
.filter(v => v !== null && v !== undefined && String(v).trim() !== '')
.join(' | ');

return [{
  json: {
    ...product,
    productText
  }
}];
